<script setup lang="ts">
import { toRefs } from 'vue'
import type { ChallengeWriteUpReviewState } from '~/features/writeups/useChallengeWriteUpReview'
const props = defineProps<{ state: ChallengeWriteUpReviewState }>()
const { selected, loading, previewLoading, pending, error, previewError, search, filter, source, page, limit, total, canManage, canJudge,
  display, submittedContent, publishedContent, submittedPdf, publishedPdf, reason, confirmation, settingsOpen, officialOpen, officialChallengeId,
  challengeOptions, selectedId, selectedVersion, publishedVersion, statusKey, pageCount, options, load, select, changePage, changeLimit, requestPublish,
  requestWithdraw, setConfirmationOpen, confirmReview, reject, openOfficial, consultation, competitionId, Settings, Editor, setDisplay, setPanel, narrow, panel, enabled, publishVersion, canPublish, canReject, publicationLabel, publicationBlocked, publicationNotice, confirmationTarget, confirmationSettings, competitionStatus, bindOfficialEditor, setOfficialOpen, changeOfficialChallenge } = toRefs(props.state)
</script>
<template>
  <section class="flex min-h-0 flex-1 flex-col gap-4">
    <header class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-semibold">{{ $t('challengeWriteUp.review') }}</h2><div class="flex flex-wrap gap-2"><Button v-if="canManage" variant="outline" @click="openOfficial">{{ $t('challengeWriteUp.official') }}</Button><Dialog v-model:open="settingsOpen"><DialogTrigger as-child><Button variant="outline">{{ $t('challengeWriteUp.settings') }}</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>{{ $t('challengeWriteUp.settings') }}</DialogTitle></DialogHeader><component :is="Settings" :competition-id="competitionId" :can-write="canManage" @saved="load" /></DialogContent></Dialog></div></header>
    <ToggleGroup v-if="narrow" type="single" :model-value="panel" :aria-label="$t('challengeWriteUp.review')" @update:model-value="setPanel"><ToggleGroupItem value="list">{{ $t('challengeWriteUp.submissions') }}</ToggleGroupItem><ToggleGroupItem value="preview" :disabled="!selected">{{ $t('challengeWriteUp.preview') }}</ToggleGroupItem><ToggleGroupItem value="actions" :disabled="!selected">{{ $t('challengeWriteUp.reviewActions') }}</ToggleGroupItem></ToggleGroup>
    <div class="grid min-h-0 flex-1 gap-5 xl:grid-cols-[15rem_minmax(0,1fr)_19rem]">
      <ChoiceSidebar v-if="!narrow || panel === 'list'" contained :items="options" :model-value="selectedId" :loading="loading" :label="$t('challengeWriteUp.review')" :loading-label="$t('challengeWriteUp.review')" :empty-label="$t('challengeWriteUp.noReview')" @update:model-value="select">
        <template #header><div class="space-y-3"><Input v-model="search" :placeholder="$t('challengeWriteUp.search')" :aria-label="$t('challengeWriteUp.search')" />
          <Select v-model="filter"><SelectTrigger :aria-label="$t('common.label.status')"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Submitted">{{ $t('challengeWriteUp.pending') }}</SelectItem><SelectItem value="Published">{{ $t('challengeWriteUp.published') }}</SelectItem><SelectItem value="Rejected">{{ $t('challengeWriteUp.rejected') }}</SelectItem><SelectItem value="Draft">{{ $t('challengeWriteUp.draft') }}</SelectItem><SelectItem value="All">{{ $t('challengeWriteUp.all') }}</SelectItem></SelectContent></Select>
          <Select v-model="source"><SelectTrigger :aria-label="$t('challengeWriteUp.source')"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="All">{{ $t('challengeWriteUp.all') }}</SelectItem><SelectItem value="Official">{{ $t('challengeWriteUp.official') }}</SelectItem><SelectItem value="Team">{{ $t('challengeWriteUp.teams') }}</SelectItem></SelectContent></Select>
        </div></template>
        <template #item="{ item }"><span class="flex min-w-0 flex-col gap-1"><span class="truncate font-medium">{{ item.row.challengeTitle }}</span><span class="truncate text-xs text-muted-foreground">{{ item.row.source === 'Official' ? $t('challengeWriteUp.official') : item.row.authorName }} · {{ $t(item.statusKey) }}</span></span></template>
        <template #footer><OffsetPagination :page="page" :page-count="pageCount" :limit="limit" :total="total" :loading="loading" @update:page="changePage" @update:limit="changeLimit" /></template>
      </ChoiceSidebar>
      <Card v-if="!narrow || panel === 'preview'" class="flex min-h-0 min-w-0 flex-col"><CardHeader v-if="selected"><CardTitle>{{ selected.challengeTitle }}</CardTitle><div class="flex flex-wrap gap-2"><Badge>{{ $t(statusKey) }}</Badge><Badge v-if="display !== 'published' && selectedVersion" variant="secondary">{{ $t('challengeWriteUp.submissionVersion') }} · {{ $t('challengeWriteUp.version', { number: selectedVersion.number ?? 1 }) }}</Badge><Badge v-if="display !== 'submitted' && publishedVersion" variant="secondary">{{ $t('challengeWriteUp.publishedVersion') }} · {{ $t('challengeWriteUp.version', { number: publishedVersion.number ?? 1 }) }}</Badge><span class="text-xs text-muted-foreground">{{ $t('challengeWriteUp.reviewedBy', { name: selectedVersion?.actorDisplayName ?? $t('challengeWriteUp.deletedUser'), time: formatDateTime(selectedVersion?.submittedAt ?? selectedVersion?.updatedAt) }) }}</span></div>
        <ToggleGroup type="single" :model-value="display" :aria-label="$t('challengeWriteUp.preview')" @update:model-value="setDisplay"><ToggleGroupItem value="submitted">{{ $t('challengeWriteUp.submissionVersion') }}</ToggleGroupItem><ToggleGroupItem value="published" :disabled="!publishedVersion">{{ $t('challengeWriteUp.publishedVersion') }}</ToggleGroupItem><ToggleGroupItem value="compare" :disabled="!publishedVersion">{{ $t('challengeWriteUp.compare') }}</ToggleGroupItem></ToggleGroup>
