          <div v-if="display !== 'submitted'" class="h-full min-h-0 min-w-0"><ScrollSurface v-if="publishedContent?.format === 'Markdown'" axis="both" class="h-full min-h-0"><MarkdownContent v-if="publishedContent?.format === 'Markdown'" :source="publishedContent.markdown ?? ''" class="max-w-[75ch] leading-7" /></ScrollSurface><PdfPreview v-else-if="publishedContent?.format === 'Pdf'" fill :source="publishedPdf" :accessible-label="$t('challengeWriteUp.publishedVersion')" :empty-label="$t('challengeWriteUp.previewEmpty')" /></div>
        </div><Empty v-else><EmptyHeader><EmptyTitle>{{ $t('challengeWriteUp.reviewEmpty') }}</EmptyTitle></EmptyHeader></Empty>
