        <FieldDescription v-if="publicationNotice">{{ $t('challengeWriteUp.submittedPublishFailed') }}</FieldDescription>
        <FieldDescription v-if="canManage && publicationBlocked">{{ $t(publicationBlocked) }}</FieldDescription>
        <Separator /><Field v-if="canJudge"><FieldLabel>{{ $t('challengeWriteUp.returnReason') }}</FieldLabel><Textarea v-model="reason" :disabled="pending" :placeholder="$t('challengeWriteUp.returnReasonPlaceholder')" /></Field>
