    <Dialog :open="officialOpen" @update:open="setOfficialOpen"><DialogContent class="flex h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] min-h-0 flex-col sm:max-w-5xl" :aria-describedby="undefined"><DialogHeader class="shrink-0 pr-8"><DialogTitle>{{ $t('challengeWriteUp.officialEditor') }}</DialogTitle></DialogHeader><Select :model-value="officialChallengeId" @update:model-value="changeOfficialChallenge"><SelectTrigger class="shrink-0" :aria-label="$t('challengeWriteUp.pickChallenge')"><SelectValue /></SelectTrigger><SelectContent><SelectItem v-for="item in challengeOptions" :key="item.value" :value="item.value">{{ item.label }}</SelectItem></SelectContent></Select><component :is="Editor" :ref="bindOfficialEditor" v-if="officialChallengeId" :key="officialChallengeId" :competition-id="competitionId" :competition-challenge-id="officialChallengeId" official embedded @saved="load" @close="setOfficialOpen(false)" /></DialogContent></Dialog>
  </section>
</template>
